<template><main class="hh-page account-detail"><router-link to="/facturacion/cuentas" class="hh-back-link"><i class="ph ph-arrow-left"></i> Cuentas hospitalarias</router-link><div v-if="loading" class="state"><span class="spinner-border text-primary"></span></div><div v-else-if="error&&!account" class="alert alert-danger mt-3">{{error}}</div><template v-else-if="account"><section class="account-hero"><div><small>CUENTA HOSPITALARIA #{{account.id||route.params.id}}</small><h1>{{account.paciente||account.nombre_paciente||'Paciente'}}</h1><p>Orden #{{account.id_orden_trabajo||'—'}} · {{account.pagador||account.tercero||'Pagador no informado'}}</p></div><span>{{account.estado||'ABIERTA'}}</span></section><div v-if="error" class="alert alert-danger mt-3">{{error}}</div><section class="summary"><article><small>Contrato</small><strong>{{account.contrato||'No informado'}}</strong></article><article><small>Modalidad</small><strong>{{account.modalidad||'No informada'}}</strong></article><article><small>Cargos</small><strong>{{charges.length}}</strong></article><article><small>Total liquidado</small><strong>{{money(account.total||totals.final)}}</strong></article></section><section class="account-actions"><div><small>ACCIONES DE CUENTA</small><h2>Control económico del episodio</h2></div><div><button class="btn btn-outline-primary" :disabled="saving" @click="run('sync')">Sincronizar cargos</button><button class="btn btn-outline-primary" :disabled="saving" @click="run('liquidate')">Liquidar</button><button v-if="!isClosed" class="btn btn-primary" :disabled="saving" @click="openConfirm('close')">Cerrar cuenta</button><button v-else class="btn btn-outline-warning" :disabled="saving" @click="openConfirm('reopen')">Reabrir</button><button v-if="isClosed" class="btn btn-success" :disabled="saving" @click="openConfirm('invoice')">Generar factura</button></div></section><div class="account-grid"><section class="charges"><header><div><small>LIBRO ÚNICO</small><h2>Cargos de la cuenta</h2></div><button class="btn btn-sm btn-outline-primary" @click="openConfirm('manual')"><i class="ph ph-plus"></i> Cargo manual</button></header><div v-if="!charges.length" class="state"><i class="ph ph-list-checks"></i><p>La cuenta no tiene cargos.</p></div><article v-for="charge in charges" :key="charge.id"><span :class="chargeClass(charge)"><i class="ph ph-receipt"></i></span><div><small>{{charge.tipo||charge.tipo_cargo}} · {{charge.estado}}</small><strong>{{charge.descripcion||charge.servicio}}</strong><p>{{charge.codigo||'Sin código'}} · {{charge.cantidad||1}} {{charge.unidad||'unidad'}}</p></div><em v-if="charge.incluido_paquete">Incluido</em><strong>{{money(charge.valor_final??charge.valor)}}</strong><button v-if="!['ANULADO','FACTURADO'].includes(charge.estado)" class="btn btn-sm btn-outline-danger" @click="selectedCharge=charge;openConfirm('void')"><i class="ph ph-x"></i></button></article></section><aside><section><header><h2>Cuadre de valores</h2></header><div class="totals"><p><span>Valor bruto</span><strong>{{money(totals.gross)}}</strong></p><p><span>Descuentos</span><strong>-{{money(totals.discounts)}}</strong></p><p><span>Pagador</span><strong>{{money(totals.payer)}}</strong></p><p><span>Usuario</span><strong>{{money(totals.user)}}</strong></p><p class="total"><span>Total</span><strong>{{money(totals.final)}}</strong></p></div></section><section class="mt-3"><header><h2>Validaciones de cierre</h2></header><div v-if="!findings.length" class="valid"><i class="ph ph-check-circle"></i>Sin bloqueos reportados</div><div v-for="finding in findings" :key="finding.codigo||finding" class="finding"><i class="ph ph-warning"></i><span>{{finding.mensaje||finding}}</span></div></section></aside></div></template><Teleport to="body"><div v-if="action" class="action-layer" @mousedown.self="close"><section class="action-modal"><header><div><small>FACTURACIÓN</small><h3>{{actionTitles[action]}}</h3></div><button class="btn-close" @click="close"></button></header><form @submit.prevent="execute"><div class="modal-body"><div v-if="modalError" class="alert alert-danger">{{modalError}}</div><template v-if="action==='manual'"><div class="row g-3"><div class="col-md-4"><label class="form-label">Tipo *</label><select v-model="form.type" class="form-select" required><option>servicio</option><option>procedimiento</option><option>honorario</option><option>medicamento</option><option>insumo</option><option>otro</option></select></div><div class="col-md-8"><label class="form-label">Descripción *</label><input v-model.trim="form.description" class="form-control" required></div><div class="col-4"><label class="form-label">Cantidad *</label><input v-model.number="form.quantity" type="number" min="1" class="form-control" required></div><div class="col-8"><label class="form-label">Tarifa *</label><input v-model.number="form.rate" type="number" min="0" class="form-control" required></div></div></template><template v-else><p>Esta acción quedará registrada en la auditoría de la cuenta.</p><label v-if="['close','reopen','void'].includes(action)" class="form-label">Motivo {{action==='reopen'||action==='void'?'*':''}}</label><textarea v-if="['close','reopen','void'].includes(action)" v-model.trim="form.reason" class="form-control" rows="3" :required="action==='reopen'||action==='void'"></textarea></template></div><footer><button type="button" class="btn btn-outline-secondary" @click="close">Cancelar</button><button class="btn btn-primary" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm me-1"></span>{{saving?'Guardando…':'Confirmar'}}</button></footer></form></section></div></Teleport></main></template>
<script setup>
import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{obtenerMensajeError}from'@/services/api';import{anularCargo,cerrarCuenta,consultarCargosCuenta,consultarCuenta,crearCargoManual,facturarCuenta,liquidarCuenta,reabrirCuenta,sincronizarCargos}from'@/services/facturacion';const route=useRoute(),router=useRouter(),account=ref(null),charges=ref([]),loading=ref(true),saving=ref(false),error=ref(''),modalError=ref(''),action=ref(''),selectedCharge=ref(null),form=reactive({reason:'',type:'servicio',description:'',quantity:1,rate:0}),array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:Array.isArray(v?.cargos)?v.cargos:[],money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Number(v||0)),findings=computed(()=>account.value?.bloqueos_cierre||account.value?.hallazgos||[]),isClosed=computed(()=>['CERRADA','FACTURADA'].includes(account.value?.estado)),totals=computed(()=>({gross:Number(account.value?.subtotal_bruto??charges.value.reduce((s,c)=>s+Number(c.valor_base??c.valor??0),0)),discounts:Number(account.value?.descuentos||0),payer:Number(account.value?.valor_pagador||0),user:Number(account.value?.valor_usuario||0),final:Number(account.value?.total??charges.value.reduce((s,c)=>s+Number(c.valor_final??c.valor??0),0))})),actionTitles={close:'Cerrar cuenta',reopen:'Reabrir cuenta',invoice:'Generar factura',manual:'Registrar cargo manual',void:'Anular cargo'},chargeClass=c=>({included:c.incluido_paquete,void:c.estado==='ANULADO'});async function load(){loading.value=true;error.value='';try{const[a,c]=await Promise.all([consultarCuenta(route.params.id),consultarCargosCuenta(route.params.id)]);account.value=a?.data||a;charges.value=array(c)}catch(e){error.value=obtenerMensajeError(e)}finally{loading.value=false}}function openConfirm(type){action.value=type;modalError.value='';Object.assign(form,{reason:'',type:'servicio',description:'',quantity:1,rate:0})}function close(){if(!saving.value){action.value='';selectedCharge.value=null}}async function run(type){saving.value=true;error.value='';try{if(type==='sync')await sincronizarCargos(route.params.id);if(type==='liquidate')await liquidarCuenta(route.params.id);await load()}catch(e){error.value=obtenerMensajeError(e)}finally{saving.value=false}}async function execute(){saving.value=true;modalError.value='';try{if(action.value==='close')await cerrarCuenta(route.params.id,form.reason);if(action.value==='reopen')await reabrirCuenta(route.params.id,form.reason);if(action.value==='manual')await crearCargoManual(route.params.id,{tipo:form.type,descripcion:form.description,cantidad:Number(form.quantity),tarifa_base:Number(form.rate)});if(action.value==='void')await anularCargo(selectedCharge.value.id,form.reason);if(action.value==='invoice'){const result=await facturarCuenta(route.params.id),id=result?.id_factura||result?.factura?.id;action.value='';if(id){await router.push(`/facturacion/facturas/${id}`);return}}close();await load()}catch(e){modalError.value=obtenerMensajeError(e)}finally{saving.value=false}}onMounted(load)
</script>
<style scoped>.state{display:grid;place-items:center;padding:4rem;color:#788896;text-align:center}.account-hero{display:flex;align-items:center;justify-content:space-between;margin-top:1rem;padding:1.3rem 1.5rem;border-radius:1rem;background:linear-gradient(120deg,#123f68,#118aa6);color:#fff}.account-hero small,.account-hero h1,.account-hero p{display:block;margin:0}.account-hero h1{font-size:1.35rem}.account-hero>span{padding:.4rem .65rem;border-radius:20px;background:#ffffff24}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:.7rem;margin-top:1rem}.summary article,.account-actions,.charges,aside>section{padding:.85rem;border:1px solid #dce6ec;border-radius:.8rem;background:#fff}.summary small,.summary strong{display:block}.summary small{color:#7b8996}.account-actions{display:flex;align-items:center;justify-content:space-between;margin-top:1rem}.account-actions h2,.charges h2,aside h2{font-size:1rem}.account-actions>div:last-child{display:flex;gap:.45rem;flex-wrap:wrap}.account-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(280px,.7fr);gap:.8rem;margin-top:1rem}.charges>header,.charges article{display:flex;align-items:center;gap:.65rem;padding:.7rem;border-bottom:1px solid #e5eaee}.charges>header{justify-content:space-between}.charges article>span{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:#eaf5fb;color:#197da4}.charges article>span.included{background:#eeeafa;color:#685bc5}.charges article>span.void{background:#f4eeee;color:#a55}.charges article>div{min-width:0;flex:1}.charges small,.charges strong,.charges p{display:block;margin:0}.charges p{color:#788794;font-size:.68rem}.charges em{padding:.2rem .4rem;border-radius:20px;background:#eeeafa;color:#685bc5;font-size:.62rem;font-style:normal}.totals p{display:flex;justify-content:space-between;padding:.45rem 0;border-bottom:1px solid #edf0f2}.totals .total{font-size:1.05rem}.valid,.finding{display:flex;gap:.5rem;padding:.65rem;border-radius:.6rem}.valid{background:#eaf8f0;color:#25815c}.finding{margin-top:.4rem;background:#fff2dd;color:#95601d}.action-layer{position:fixed;inset:0;z-index:2100;display:grid;place-items:center;background:#071522bd}.action-modal{width:min(580px,calc(100% - 2rem));border-radius:1rem;background:#fff}.action-modal>header,.action-modal footer{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.2rem;border-bottom:1px solid #e3e9ed}.action-modal .modal-body{padding:1.2rem}.action-modal footer{justify-content:flex-end;gap:.5rem;border-top:1px solid #e3e9ed;border-bottom:0}@media(max-width:900px){.account-grid{grid-template-columns:1fr}.summary{grid-template-columns:repeat(2,1fr)}.account-actions{align-items:flex-start;flex-direction:column;gap:.7rem}}@media(max-width:550px){.summary{grid-template-columns:1fr}}</style>
